Here is a sample JSON schema that represents a standard trade approval workflow:
```
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Trade Approval Workflow",
  "type": "object",
  "properties": {
    "trade": {
      "type": "object",
      "properties": {
        "id": {"type": "string", "description": "Unique trade identifier"},
        "type": {"type": "string", "enum": ["buy", "sell"]},
        "instrument": {"type": "string", "description": "Instrument being traded (e.g. stock, bond, etc.)"},
        "quantity": {"type": "integer", "minimum": 1},
        "price": {"type": "number", "minimum": 0},
        "counterparty": {"type": "string", "description": "Counterparty to the trade"}
      },
      "required": ["id", "type", "instrument", "quantity", "price", "counterparty"]
    },
    "approvalStatus": {
      "type": "string",
      "enum": ["pending", "approved", "rejected", "cancelled"]
    },
    "approvals": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "approver": {"type": "string", "description": "Name or ID of approver"},
          "role": {"type": "string", "description": "Role of approver (e.g. trader, risk manager, etc.)"},
          "decision": {"type": "string", "enum": ["approved", "rejected"]},
          "timestamp": {"type": "string", "format": "date-time"}
        },
        "required": ["approver", "role", "decision", "timestamp"]
      }
    },
    "comments": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "author": {"type": "string", "description": "Name or ID of comment author"},
          "comment": {"type": "string", "description": "Comment text"},
          "timestamp": {"type": "string", "format": "date-time"}
        },
        "required": ["author", "comment", "timestamp"]
      }
    }
  },
  "required": ["trade", "approvalStatus"]
}
