Below is a simplified JSON schema that represents a standard regulatory submission review workflow. This schema includes common elements found in many regulatory submission review processes, but please note that specific requirements can vary significantly depending on the jurisdiction, type of submission (e.g., drug, device, etc.), and the regulatory body involved. You may need to adjust this schema to fit the specific needs of your system.

```json
{
  "$schema": "http://json-schema.org/draft-07/schema#",
  "title": "Regulatory Submission Review Workflow",
  "type": "object",
  "properties": {
    "submissionId": {"type": "string", "description": "Unique identifier for the submission"},
    "submissionType": {"type": "string", "description": "Type of submission (e.g., NDA, BLA, 510(k), etc.)"},
    "applicant": {
      "type": "object",
      "properties": {
        "name": {"type": "string"},
        "contactInformation": {
          "type": "object",
          "properties": {
            "email": {"type": "string", "format": "email"},
            "phone": {"type": "string"}
          },
          "required": ["email", "phone"]
        }
      },
      "required": ["name", "contactInformation"]
    },
    "submissionDate": {"type": "string", "format": "date-time"},
    "reviewStatus": {
      "type": "string",
      "enum": ["Received", "Under Review", "Approved", "Rejected", "Withdrawn"]
    },
    "reviewSteps": {
      "type": "array",
      "items": {
        "type": "object",
        "properties": {
          "stepName": {"type": "string"},
          "stepStatus": {
            "type": "string",
            "enum": ["Not Started", "In Progress", "Completed"]
          },
          "startDate": {"type": "string", "format": "date-time"},
          "endDate": {"type": "string", "format": "date-time"},
          "reviewer": {
            "type": "object",
            "properties": {
              "name": {"type": "string"},
              "role": {"type": "string"}
            },
            "required": ["name", "role"]
          }
        },
        "required": ["stepName", "stepStatus", "startDate", "reviewer"]
      }

